/**
 * 听写往别的应用写字:macOS 那一半。零依赖 —— 一段 JXA(osascript -l JavaScript)经 ObjC 桥直调系统 API:
 *   - 前台应用 / 前台窗口:NSWorkspace.frontmostApplication + CGWindowListCopyWindowInfo(窗口号与归属进程**不要**屏幕录制权限,标题才要,这里不取)。
 *   - 密码框:IsSecureEventInputEnabled()(零权限、跨进程;Cocoa 的 NSSecureTextField 与 Chromium 的密码框都会点亮它),
 *     有辅助功能授权时再看焦点元素的 subrole 是不是 AXSecureTextField。
 *   - 还在打字(可能在用输入法组字):CGEventSourceSecondsSinceLastEventType(键盘)+ 修饰键全松开。别的应用的组字状态从公开 API 读不到,
 *     这里等的是「键盘安静下来」,等不到就不写、留复制。
 *   - 剪贴板:快照**每一项的每一种类型**(NSPasteboardItem 全量,文件 / 图片 / 富文本都在)→ 写我们的字(带 org.nspasteboard
 *     Transient / AutoGenerated 标记,剪贴板历史工具据此不记)→ ⌘V → 等一会儿 → changeCount 没变才还原;变了 = 别人(或目标应用)
 *     改过剪贴板,不动。快照超过上限就不写(宁可留「复制」也不弄丢用户剪贴板里的大东西)。
 *   - ⌘V:CGEventPost。要 Forsion 有辅助功能授权(osascript 由 Forsion 拉起,TCC 记在 Forsion 头上);没有就回 no-permission。
 * 输入经 stdin 给(听写的文字不进命令行参数 —— ps 看得见参数)。
 *
 * 测试口子:`pasteboard` 给了名字(私有剪贴板)时才认 `checks:false` / `mutateAfterPost`,并且绝不发按键 —— 台架和单测用它测快照 / 还原,
 * 碰不到用户的剪贴板,也不会把字粘进用户此刻在用的应用。
 */
import { spawn } from 'node:child_process'
import type { DictationFailure } from '../../shared/dictation'

export interface MacFront { pid: number; bundleId?: string; name?: string; window?: number }
export interface MacInsertRequest {
  text: string
  target?: { pid: number; window?: number }
  /** 私有剪贴板名(测试);缺省 = 系统剪贴板。 */
  pasteboard?: string
  /** 只在私有剪贴板上认:false = 跳过前台 / 密码框 / 打字 / 授权这几道核对。 */
  checks?: boolean
  /** 只在私有剪贴板上认:模拟「粘贴之后别人改了剪贴板」。 */
  mutateAfterPost?: string
  /** 键盘安静多久才写(秒)。 */
  quiet?: number
  /** 最多等多久(秒)。 */
  maxWait?: number
  /** 发完 ⌘V 等多久再看剪贴板(秒):目标应用读剪贴板是异步的。 */
  settle?: number
}
export type MacInsertResult = { outcome: 'pasted'; restored: boolean | 'changed' | 'empty' } | { outcome: DictationFailure; detail?: string }

/** JXA 本体。run() 读 stdin 一行 JSON,回一行 JSON(osascript 把 run 的返回值打到 stdout)。 */
export const MAC_DRIVER_SCRIPT = String.raw`
ObjC.import('Foundation'); ObjC.import('AppKit'); ObjC.import('CoreGraphics'); ObjC.import('Carbon'); ObjC.import('ApplicationServices')
var SNAPSHOT_CAP = 64 * 1024 * 1024
function input() {
  var data = $.NSFileHandle.fileHandleWithStandardInput.readDataToEndOfFile
  var s = $.NSString.alloc.initWithDataEncoding(data, $.NSUTF8StringEncoding)
  return JSON.parse(ObjC.unwrap(s) || '{}')
}
function front() {
  var app = $.NSWorkspace.sharedWorkspace.frontmostApplication
  if (!app || app.isNil()) return null
  var pid = Number(app.processIdentifier)
  var out = { pid: pid, bundleId: ObjC.unwrap(app.bundleIdentifier) || undefined, name: ObjC.unwrap(app.localizedName) || undefined }
  var list = ObjC.deepUnwrap(ObjC.castRefToObject($.CGWindowListCopyWindowInfo(1 | 16, 0))) || []
  for (var i = 0; i < list.length; i++) {
    var w = list[i]
    if (Number(w.kCGWindowOwnerPID) === pid && Number(w.kCGWindowLayer) === 0) { out.window = Number(w.kCGWindowNumber); break }
  }
  return out
}
function axString(el, attr) {
  var ref = Ref()
  if ($.AXUIElementCopyAttributeValue(el, $(attr), ref) !== 0) return ''
  try { return ObjC.unwrap(ObjC.castRefToObject(ref[0])) || '' } catch (e) { return '' }
}
function secureField() {
  if ($.IsSecureEventInputEnabled()) return true
  if (!$.AXIsProcessTrusted()) return false
  try {
    var ref = Ref()
    if ($.AXUIElementCopyAttributeValue($.AXUIElementCreateSystemWide(), $('AXFocusedUIElement'), ref) !== 0) return false
    var el = ref[0]
    return axString(el, 'AXSubrole') === 'AXSecureTextField' || axString(el, 'AXRole') === 'AXSecureTextField'
  } catch (e) { return false }
}
function modifiersDown() {
  // kCGEventSourceStateHIDSystemState = 1; shift, control, option, command, fn
  return (Number($.CGEventSourceFlagsState(1)) & (0x20000 | 0x40000 | 0x80000 | 0x100000 | 0x800000)) !== 0
}
function keyIdle() {
  // kCGEventSourceStateCombinedSessionState = 0; kCGEventKeyDown = 10, kCGEventFlagsChanged = 12
  return Math.min(Number($.CGEventSourceSecondsSinceLastEventType(0, 10)), Number($.CGEventSourceSecondsSinceLastEventType(0, 12)))
}
function snapshot(pb) {
  var items = pb.pasteboardItems, out = [], size = 0
  if (!items || items.isNil()) return out
  var n = Number(items.count)
  for (var i = 0; i < n; i++) {
    var it = items.objectAtIndex(i), types = it.types, entry = [], m = Number(types.count)
    for (var j = 0; j < m; j++) {
      var t = types.objectAtIndex(j), d = it.dataForType(t)
      if (!d || d.isNil()) continue
      size += Number(d.length)
      if (size > SNAPSHOT_CAP) return null
      entry.push([t, d])
    }
    out.push(entry)
  }
  return out
}
function restore(pb, snap) {
  pb.clearContents
  if (!snap.length) return true
  var arr = $.NSMutableArray.alloc.init
  for (var i = 0; i < snap.length; i++) {
    var it = $.NSPasteboardItem.alloc.init
    for (var j = 0; j < snap[i].length; j++) it.setDataForType(snap[i][j][1], snap[i][j][0])
    arr.addObject(it)
  }
  return pb.writeObjects(arr)
}
function writeText(pb, text, transient) {
  pb.clearContents
  var it = $.NSPasteboardItem.alloc.init
  it.setStringForType($(text), $.NSPasteboardTypeString)
  if (transient) {
    it.setStringForType($(''), $('org.nspasteboard.TransientType'))
    it.setStringForType($(''), $('org.nspasteboard.AutoGeneratedType'))
  }
  var arr = $.NSMutableArray.alloc.init
  arr.addObject(it)
  return pb.writeObjects(arr)
}
function postPaste() {
  var down = $.CGEventCreateKeyboardEvent(null, 9, true)   // kVK_ANSI_V
  $.CGEventSetFlags(down, 0x100000)                      // ⌘ only, whatever else is physically held
  var up = $.CGEventCreateKeyboardEvent(null, 9, false)
  $.CGEventSetFlags(up, 0x100000)
  $.CGEventPost(0, down)                                  // kCGHIDEventTap
  $.CGEventPost(0, up)
}
function insert(req) {
  var named = typeof req.pasteboard === 'string' && req.pasteboard.length > 0
  var pb = named ? $.NSPasteboard.pasteboardWithName($(req.pasteboard)) : $.NSPasteboard.generalPasteboard
  var checks = !(named && req.checks === false)
  if (checks) {
    if (!req.target || typeof req.target.pid !== 'number') return { outcome: 'target-changed', detail: 'no target' }
    var f = front()
    if (!f || f.pid !== req.target.pid) return { outcome: 'target-changed' }
    if (req.target.window && f.window && f.window !== req.target.window) return { outcome: 'target-changed', detail: 'window' }
    if (secureField()) return { outcome: 'secure-field' }
    if (!named && !$.AXIsProcessTrusted()) return { outcome: 'no-permission' }
    var quiet = typeof req.quiet === 'number' ? req.quiet : 0.35, maxWait = typeof req.maxWait === 'number' ? req.maxWait : 4
    var waited = 0
    while (keyIdle() < quiet || modifiersDown()) {
      if (waited >= maxWait) return { outcome: 'still-typing' }
      delay(0.05); waited += 0.05
    }
    // the user may have switched apps while we waited
    var again = front()
    if (!again || again.pid !== req.target.pid) return { outcome: 'target-changed' }
    if (secureField()) return { outcome: 'secure-field' }
  }
  var snap = snapshot(pb)
  if (snap === null) return { outcome: 'paste-failed', detail: 'clipboard too large to keep' }
  if (!writeText(pb, req.text, true)) return { outcome: 'paste-failed', detail: 'write' }
  var mine = Number(pb.changeCount)
  if (!named) postPaste()
  delay(typeof req.settle === 'number' ? req.settle : 0.4)
  if (named && typeof req.mutateAfterPost === 'string') writeText(pb, req.mutateAfterPost, false)
  if (Number(pb.changeCount) !== mine) return { outcome: 'pasted', restored: 'changed' }
  if (!snap.length) { pb.clearContents; return { outcome: 'pasted', restored: 'empty' } }
  return { outcome: 'pasted', restored: !!restore(pb, snap) }
}
function run() {
  var req = input()
  try {
    if (req.op === 'front') return JSON.stringify({ front: front() })
    if (req.op === 'probe') return JSON.stringify({ ax: !!$.AXIsProcessTrusted(), secure: !!$.IsSecureEventInputEnabled() })
    if (req.op === 'insert') return JSON.stringify(insert(req))
    if (req.op === 'copy') {
      var named = typeof req.pasteboard === 'string' && req.pasteboard.length > 0
      var pb = named ? $.NSPasteboard.pasteboardWithName($(req.pasteboard)) : $.NSPasteboard.generalPasteboard
      return JSON.stringify({ ok: !!writeText(pb, req.text, false) })
    }
    return JSON.stringify({ error: 'unknown op' })
  } catch (e) { return JSON.stringify({ error: String(e) }) }
}
`

export type RunJxa = (script: string, input: string, timeoutMs: number) => Promise<string>

export const runOsascript: RunJxa = (script, input, timeoutMs) => new Promise((resolve, reject) => {
  const child = spawn('/usr/bin/osascript', ['-l', 'JavaScript', '-e', script], { stdio: ['pipe', 'pipe', 'pipe'] })
  let out = ''
  let err = ''
  const timer = setTimeout(() => { child.kill('SIGKILL'); reject(new Error('osascript timed out')) }, timeoutMs)
  child.stdout.setEncoding('utf8').on('data', (c: string) => { out += c })
  child.stderr.setEncoding('utf8').on('data', (c: string) => { err += c })
  child.on('error', (e) => { clearTimeout(timer); reject(e) })
  child.on('close', (code) => {
    clearTimeout(timer)
    if (code === 0) resolve(out.trim())
    else reject(new Error(`osascript exited ${code}: ${err.trim().slice(0, 300)}`))
  })
  child.stdin.end(input, 'utf8')
})

export interface MacDriver {
  front(): Promise<MacFront | null>
  insert(req: MacInsertRequest): Promise<MacInsertResult>
  copy(text: string, pasteboard?: string): Promise<boolean>
  probe(): Promise<{ ax: boolean; secure: boolean }>
}

const FAILURES: readonly string[] = ['target-changed', 'secure-field', 'still-typing', 'no-permission', 'paste-failed']

export function createMacDriver(run: RunJxa = runOsascript): MacDriver {
  const call = async (payload: Record<string, unknown>, timeoutMs: number): Promise<Record<string, unknown>> => {
    const raw = await run(MAC_DRIVER_SCRIPT, JSON.stringify(payload), timeoutMs)
    const parsed = JSON.parse(raw) as Record<string, unknown>
    if (typeof parsed.error === 'string') throw new Error(parsed.error)
    return parsed
  }
  return {
    async front() {
      const r = await call({ op: 'front' }, 5_000)
      const f = r.front as Record<string, unknown> | null
      if (!f || typeof f.pid !== 'number' || f.pid <= 0) return null
      return {
        pid: f.pid,
        ...(typeof f.bundleId === 'string' ? { bundleId: f.bundleId } : {}),
        ...(typeof f.name === 'string' ? { name: f.name } : {}),
        ...(typeof f.window === 'number' && f.window > 0 ? { window: f.window } : {}),
      }
    },
    async insert(req) {
      const maxWait = req.maxWait ?? 4
      const r = await call({ op: 'insert', ...req }, (maxWait + 10) * 1000)
      if (r.outcome === 'pasted') {
        const restored = r.restored === 'changed' || r.restored === 'empty' ? r.restored : r.restored === true
        return { outcome: 'pasted', restored }
      }
      const outcome = typeof r.outcome === 'string' && FAILURES.includes(r.outcome) ? r.outcome as DictationFailure : 'paste-failed'
      return { outcome, ...(typeof r.detail === 'string' ? { detail: r.detail } : {}) }
    },
    async copy(text, pasteboard) {
      const r = await call({ op: 'copy', text, ...(pasteboard ? { pasteboard } : {}) }, 5_000)
      return r.ok === true
    },
    async probe() {
      const r = await call({ op: 'probe' }, 5_000)
      return { ax: r.ax === true, secure: r.secure === true }
    },
  }
}
